// Assemble a six-page theme pack from a JSON config (scripts/packs/<id>.json) into one paid pack. The pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for Divi 5 plugin from its section
// recipes in the validator repo (php scripts/theme-packs/build.php <id> -> dist/theme-packs/<id>/<role>.json) and then run
// through every downstream gate here (validate, stock photos, design lint, mobile stacking, dedupe, SEO, real Divi render,
// critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && PACK=<id> PACK_DIR=<dir with the json files> npx tsx scripts/pack-create.ts
// Smoke test or split across workers: THEME_ONLY_ROLES=home,work. Publish to production: scripts/pack-publish.sh <id>.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

export interface PackConfig {
  id: string;
  businessName: string;
  tagline: string;
  audience: string;
  conversionGoal: string;
  primaryCta: string;
  accentColorHex: string;
  voice: string;
  palette: Brief['palette'];
  designNotes: string;
  brandFacts: string;
  roles: { role: string; roleLabel: string }[];
  niche: string;
  style: string;
  color: string;
  packSlug: string;
  packTitle: string;
  description: string;
  seo: { metaTitle: string; metaDescription: string; keywords: string[] };
  priceCents?: number;
}

const ID = process.env.PACK;
if (!ID) throw new Error('set PACK=<id> (scripts/packs/<id>.json)');
const CFG = JSON.parse(readFileSync(`scripts/packs/${ID}.json`, 'utf8')) as PackConfig;
const DIR = process.env.PACK_DIR ?? `../Divi 5 Deterministic Validator/dist/theme-packs/${ID}`;

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: CFG.businessName,
  tagline: CFG.tagline,
  audience: CFG.audience,
  conversionGoal: CFG.conversionGoal,
  primaryCta: CFG.primaryCta,
  accentColorHex: CFG.accentColorHex,
  voice: CFG.voice,
  palette: CFG.palette,
  designNotes: CFG.designNotes,
};

const PAGES: ThemePage[] = CFG.roles.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: CFG.niche, style: CFG.style, color: CFG.color, brief: BRIEF, brandFacts: CFG.brandFacts, pages: PAGES };
const PRICE_CENTS = CFG.priceCents ?? 1200;

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no pack pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, CFG.packSlug)).limit(1))[0];
  const common = {
    title: CFG.packTitle, description: CFG.description, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: CFG.seo, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: CFG.packSlug, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${CFG.packSlug}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
